-- Query 1: CUSTOMER - ORDERS - RESTAURANT - DRIVER, kèm ghi chú và tùy chọn món.
-- Một dòng / ORDER_ITEM. Đơn chưa có tài xế vẫn xuất hiện (LEFT JOIN).
-- Chọn lần phân công mới nhất; tổng hợp ghi chú/tùy chọn riêng để tránh nhân dòng.
WITH RankedAssignments AS (
    SELECT da.*, ROW_NUMBER() OVER (
        PARTITION BY da.order_id ORDER BY da.assigned_at DESC, da.assignment_id DESC
    ) AS rn
    FROM DELIVERY_ASSIGNMENT da
), OrderNotes AS (
    SELECT order_id, JSON_ARRAYAGG(note_text) AS order_notes
    FROM ORDER_NOTE GROUP BY order_id
), ItemCustomizations AS (
    SELECT order_item_id, JSON_ARRAYAGG(customization_name) AS item_customizations
    FROM ORDER_ITEM_CUSTOMIZATION GROUP BY order_item_id
)
SELECT o.order_id, o.order_time,
       CONCAT(c.last_name, ' ', c.first_name) AS customer_name,
       r.name AS restaurant_name,
       CONCAT(d.last_name, ' ', d.first_name) AS driver_name,
       da.status AS assignment_status, cs.status AS current_order_status,
       oi.order_item_id, mi.name AS dish_name, v.variant_name,
       oi.quantity, oi.unit_price, oi.quantity * oi.unit_price AS line_total,
       COALESCE(n.order_notes, JSON_ARRAY()) AS order_notes,
       COALESCE(ic.item_customizations, JSON_ARRAY()) AS item_customizations,
       o.total_amount AS order_total
FROM ORDERS o
JOIN CUSTOMER c ON c.customer_id = o.customer_id
JOIN RESTAURANT r ON r.restaurant_id = o.restaurant_id
LEFT JOIN RankedAssignments da ON da.order_id = o.order_id AND da.rn = 1
LEFT JOIN DRIVER d ON d.driver_id = da.driver_id
LEFT JOIN ORDER_CURRENT_STATUS cs ON cs.order_id = o.order_id
LEFT JOIN ORDER_ITEM oi ON oi.order_id = o.order_id
LEFT JOIN MENU_ITEM_VARIANT v ON v.variant_id = oi.variant_id
LEFT JOIN MENU_ITEM mi ON mi.menu_item_id = v.menu_item_id
LEFT JOIN OrderNotes n ON n.order_id = o.order_id
LEFT JOIN ItemCustomizations ic ON ic.order_item_id = oi.order_item_id
ORDER BY o.order_id, oi.order_item_id;
-- order_total lặp theo dòng món: không SUM cột này trên kết quả chi tiết.

-- Query 2: Tìm khách hàng VIP có tổng chi tiêu (đơn đã giao) cao hơn mức trung bình toàn hệ thống
-- Kỹ thuật: INNER JOIN, Aggregation, HAVING kết hợp Subquery không tương quan
SELECT
    c.customer_id,
    CONCAT(c.first_name, ' ', c.last_name) AS customer_name,
    c.email,
    COUNT(o.order_id) AS delivered_order_count,
    SUM(o.total_amount) AS total_spent
FROM CUSTOMER AS c
INNER JOIN ORDERS AS o
    ON o.customer_id = c.customer_id
INNER JOIN ORDER_CURRENT_STATUS AS ocs
    ON ocs.order_id = o.order_id
WHERE ocs.status = 'Delivered'
GROUP BY
    c.customer_id,
    c.first_name,
    c.last_name,
    c.email
HAVING SUM(o.total_amount) > (
    SELECT AVG(customer_spending.total_paid)
    FROM (
        SELECT
            o2.customer_id,
            SUM(o2.total_amount) AS total_paid
        FROM ORDERS AS o2
        INNER JOIN ORDER_CURRENT_STATUS AS ocs2
            ON ocs2.order_id = o2.order_id
        WHERE ocs2.status = 'Delivered'
        GROUP BY o2.customer_id
    ) AS customer_spending
)
ORDER BY
    total_spent DESC;

-- Query 3: Top 5 biến thể món ăn bán chạy nhất và tỷ trọng (%) trên tổng số lượng món đã bán
-- Kỹ thuật: Multi-table INNER JOIN, Aggregation, Scalar Subquery trong SELECT
SELECT
    r.name AS restaurant_name,
    mi.name AS menu_item_name,
    v.variant_name,
    SUM(oi.quantity) AS total_quantity_sold,
    SUM(oi.quantity * oi.unit_price) AS gross_item_revenue,
    ROUND(
        SUM(oi.quantity) * 100.0 / (
            SELECT SUM(oi2.quantity)
            FROM ORDER_ITEM AS oi2
            INNER JOIN ORDER_CURRENT_STATUS AS ocs2
                ON ocs2.order_id = oi2.order_id
            WHERE ocs2.status = 'Delivered'
        ),
        2
    ) AS quantity_share_pct
FROM ORDER_ITEM AS oi
INNER JOIN ORDERS AS o
    ON o.order_id = oi.order_id
INNER JOIN ORDER_CURRENT_STATUS AS ocs
    ON ocs.order_id = o.order_id
INNER JOIN MENU_ITEM_VARIANT AS v
    ON v.variant_id = oi.variant_id
INNER JOIN MENU_ITEM AS mi
    ON mi.menu_item_id = v.menu_item_id
INNER JOIN RESTAURANT AS r
    ON r.restaurant_id = mi.restaurant_id
WHERE ocs.status = 'Delivered'
GROUP BY
    r.restaurant_id,
    r.name,
    mi.menu_item_id,
    mi.name,
    v.variant_id,
    v.variant_name
ORDER BY
    total_quantity_sold DESC,
    gross_item_revenue DESC
LIMIT 5;

-- Query 4: Đánh giá hiệu suất giao hàng và thời gian hoàn thành trung bình của từng tài xế
-- Kỹ thuật: LEFT JOIN, Conditional Aggregation (CASE WHEN), TIMESTAMPDIFF
SELECT
    d.driver_id,
    CONCAT(d.first_name, ' ', d.last_name) AS driver_name,
    d.vehicle_type,
    COUNT(da.assignment_id) AS total_assignments,
    SUM(CASE WHEN da.status = 'Completed' THEN 1 ELSE 0 END) AS completed_deliveries,
    SUM(CASE WHEN da.status = 'Failed' THEN 1 ELSE 0 END) AS failed_deliveries,
    SUM(CASE WHEN da.status = 'Rejected' THEN 1 ELSE 0 END) AS rejected_assignments,
    ROUND(
        SUM(CASE WHEN da.status = 'Completed' THEN 1 ELSE 0 END) * 100.0
        / NULLIF(COUNT(da.assignment_id), 0),
        2
    ) AS completion_rate_pct,
    ROUND(
        AVG(
            CASE
                WHEN da.status = 'Completed'
                    THEN TIMESTAMPDIFF(MINUTE, da.accepted_at, da.completed_at)
                ELSE NULL
            END
        ),
        1
    ) AS avg_delivery_minutes
FROM DRIVER AS d
LEFT JOIN DELIVERY_ASSIGNMENT AS da
    ON da.driver_id = d.driver_id
GROUP BY
    d.driver_id,
    d.first_name,
    d.last_name,
    d.vehicle_type
ORDER BY
    completed_deliveries DESC,
    completion_rate_pct DESC;

-- Query 5: Tìm khách hàng đã đặt từ 2 đơn giao thành công trở lên nhưng chưa từng viết đánh giá
-- Kỹ thuật: INNER JOIN, GROUP BY, HAVING, Subquery với NOT EXISTS
SELECT
    c.customer_id,
    CONCAT(c.first_name, ' ', c.last_name) AS customer_name,
    c.email,
    c.phone_number,
    COUNT(o.order_id) AS completed_orders,
    SUM(o.total_amount) AS total_spent
FROM CUSTOMER AS c
INNER JOIN ORDERS AS o
    ON o.customer_id = c.customer_id
INNER JOIN ORDER_CURRENT_STATUS AS ocs
    ON ocs.order_id = o.order_id
WHERE ocs.status = 'Delivered'
  AND NOT EXISTS (
      SELECT 1
      FROM REVIEW AS rv
      WHERE rv.customer_id = c.customer_id
  )
GROUP BY
    c.customer_id,
    c.first_name,
    c.last_name,
    c.email,
    c.phone_number
HAVING COUNT(o.order_id) >= 2
ORDER BY
    completed_orders DESC;

-- Query 6: Tìm món ăn (biến thể) có mức giá cao nhất trong thực đơn của từng nhà hàng
-- Kỹ thuật: INNER JOIN kết hợp Correlated Subquery (truy vấn con tương quan)
SELECT
    r.restaurant_id,
    r.name AS restaurant_name,
    mi.name AS menu_item_name,
    v.variant_name,
    v.price AS highest_price
FROM RESTAURANT AS r
INNER JOIN MENU_ITEM AS mi
    ON mi.restaurant_id = r.restaurant_id
INNER JOIN MENU_ITEM_VARIANT AS v
    ON v.menu_item_id = mi.menu_item_id
WHERE v.price = (
    SELECT MAX(v2.price)
    FROM MENU_ITEM_VARIANT AS v2
    INNER JOIN MENU_ITEM AS mi2
        ON mi2.menu_item_id = v2.menu_item_id
    WHERE mi2.restaurant_id = r.restaurant_id
)
ORDER BY
    v.price DESC,
    r.name ASC;

-- Query 7: Xếp hạng Top 3 món ăn bán chạy nhất trong nội bộ từng nhà hàng
-- Kỹ thuật: Common Table Expression (CTE), Window Function (DENSE_RANK), JOIN
WITH restaurant_item_sales AS (
    SELECT
        r.restaurant_id,
        r.name AS restaurant_name,
        mi.menu_item_id,
        mi.name AS menu_item_name,
        SUM(oi.quantity) AS total_units_sold,
        SUM(oi.quantity * oi.unit_price) AS item_revenue,
        DENSE_RANK() OVER (
            PARTITION BY r.restaurant_id
            ORDER BY SUM(oi.quantity) DESC, SUM(oi.quantity * oi.unit_price) DESC
        ) AS rank_in_restaurant
    FROM RESTAURANT AS r
    INNER JOIN ORDERS AS o
        ON o.restaurant_id = r.restaurant_id
    INNER JOIN ORDER_CURRENT_STATUS AS ocs
        ON ocs.order_id = o.order_id
    INNER JOIN ORDER_ITEM AS oi
        ON oi.order_id = o.order_id
    INNER JOIN MENU_ITEM_VARIANT AS v
        ON v.variant_id = oi.variant_id
    INNER JOIN MENU_ITEM AS mi
        ON mi.menu_item_id = v.menu_item_id
    WHERE ocs.status = 'Delivered'
    GROUP BY
        r.restaurant_id,
        r.name,
        mi.menu_item_id,
        mi.name
)
SELECT
    restaurant_name,
    rank_in_restaurant,
    menu_item_name,
    total_units_sold,
    item_revenue
FROM restaurant_item_sales
WHERE rank_in_restaurant <= 3
ORDER BY
    restaurant_name ASC,
    rank_in_restaurant ASC;

-- Query 8: Đối soát lịch sử tích điểm (EARN), đổi điểm (REDEEM) và số dư điểm của khách hàng
-- Kỹ thuật: INNER JOIN, Conditional Aggregation, gọi Stored Function GetLoyaltyBalance
SELECT
    c.customer_id,
    CONCAT(c.first_name, ' ', c.last_name) AS customer_name,
    COUNT(lt.loyalty_transaction_id) AS total_transactions,
    SUM(CASE WHEN lt.transaction_type = 'EARN' THEN lt.points ELSE 0 END) AS total_earned_points,
    SUM(CASE WHEN lt.transaction_type = 'REDEEM' THEN ABS(lt.points) ELSE 0 END) AS total_redeemed_points,
    GetLoyaltyBalance(c.customer_id) AS current_point_balance
FROM CUSTOMER AS c
INNER JOIN LOYALTY_TRANSACTION AS lt
    ON lt.customer_id = c.customer_id
GROUP BY
    c.customer_id,
    c.first_name,
    c.last_name
ORDER BY
    current_point_balance DESC;
-- Query 10: Thống kê doanh thu, số đơn hoàn thành và điểm đánh giá trung bình của từng nhà hàng
-- Kỹ thuật: Truy vấn từ View tổng hợp kết hợp lọc điều kiện
SELECT
    restaurant_id,
    restaurant_name,
    total_delivered_orders,
    total_revenue,
    total_reviews,
    COALESCE(average_rating, 0.00) AS average_rating
FROM RESTAURANT_PERFORMANCE_SUMMARY
ORDER BY
    total_revenue DESC,
    average_rating DESC;
-- Query 11: Phân tích khung giờ cao điểm đặt hàng trong ngày và tỷ trọng doanh thu
-- Kỹ thuật: Date/Time Extraction (HOUR), Aggregation, Scalar Subquery
SELECT
    HOUR(o.order_time) AS order_hour,
    COUNT(o.order_id) AS total_orders,
    SUM(o.total_amount) AS hourly_revenue,
    ROUND(AVG(o.total_amount), 2) AS avg_hourly_order_value,
    ROUND(
        COUNT(o.order_id) * 100.0 / (SELECT COUNT(*) FROM ORDERS),
        2
    ) AS order_volume_pct
FROM ORDERS AS o
GROUP BY
    HOUR(o.order_time)
ORDER BY
    total_orders DESC,
    order_hour ASC;

-- Query 13: Liệt kê các biến thể món ăn có giá bán cao hơn giá trung bình toàn thực đơn,
-- kèm theo tên nhà hàng và tổng số lượng đã được đặt
-- Kỹ thuật: Multi-table JOIN, Subquery đơn giản, Aggregation (SUM + GROUP BY)
SELECT
    r.name AS restaurant_name,
    mi.name AS menu_item_name,
    v.variant_name,
    v.price,
    COALESCE(SUM(oi.quantity), 0) AS total_quantity_sold
FROM MENU_ITEM_VARIANT AS v
INNER JOIN MENU_ITEM AS mi
    ON mi.menu_item_id = v.menu_item_id
INNER JOIN RESTAURANT AS r
    ON r.restaurant_id = mi.restaurant_id
LEFT JOIN ORDER_ITEM AS oi
    ON oi.variant_id = v.variant_id
WHERE v.price > (
    SELECT AVG(price)
    FROM MENU_ITEM_VARIANT
)
GROUP BY
    r.name,
    mi.name,
    v.variant_id,
    v.variant_name,
    v.price
ORDER BY
    v.price DESC,
    total_quantity_sold DESC;


-- ===================================================================
-- 5.0. ĐỐI SOÁT DỮ LIỆU MẪU: mỗi dòng phải có violation_count = 0
-- ===================================================================
WITH Balances AS (
    SELECT customer_id, points, created_at,
           SUM(points) OVER (PARTITION BY customer_id
             ORDER BY created_at, loyalty_transaction_id ROWS UNBOUNDED PRECEDING) AS balance
    FROM LOYALTY_TRANSACTION
), ItemTotals AS (
    SELECT order_id, SUM(unit_price * quantity) AS amount FROM ORDER_ITEM GROUP BY order_id
)
SELECT 'Order subtotal vs items' AS audit_name, COUNT(*) AS violation_count
FROM ORDERS o LEFT JOIN ItemTotals it ON it.order_id = o.order_id
WHERE o.subtotal <> COALESCE(it.amount, 0)
UNION ALL
SELECT 'Negative historical loyalty balance', COUNT(*) FROM Balances WHERE balance < 0
UNION ALL
SELECT 'Loyalty before order or wrong customer', COUNT(*)
FROM LOYALTY_TRANSACTION lt JOIN ORDERS o ON o.order_id = lt.order_id
WHERE lt.created_at < o.order_time OR lt.customer_id <> o.customer_id
UNION ALL
SELECT 'Review of a non-delivered order', COUNT(*)
FROM REVIEW rv LEFT JOIN ORDER_CURRENT_STATUS cs ON cs.order_id = rv.order_id
WHERE cs.status IS NULL OR cs.status <> 'Delivered' OR rv.created_at < cs.changed_at
UNION ALL
SELECT 'Delivery completion vs history', COUNT(*)
FROM DELIVERY_ASSIGNMENT da JOIN ORDER_CURRENT_STATUS cs ON cs.order_id = da.order_id
WHERE (da.status = 'Completed' AND (cs.status <> 'Delivered' OR cs.changed_at <> da.completed_at))
   OR (da.status = 'Failed' AND (cs.status <> 'Delivery Failed' OR cs.changed_at <> da.completed_at));

-- ===================================================================
-- 5.1. NEGATIVE TEST CASES - chạy tự động, không cần bật Continue on error
-- ===================================================================
-- Chạy sau dữ liệu mẫu, ngoài transaction của ứng dụng.
-- ID âm được dành riêng cho fixture để không tăng AUTO_INCREMENT của dữ liệu mẫu.
-- Mỗi case có SAVEPOINT, bắt lỗi, kiểm tra MYSQL_ERRNO và tên CHECK/FK/thông báo.
-- Kết quả PASS chỉ khi đúng lỗi dự kiến; bắt được lỗi khác vẫn là FAIL.
-- Các ca này chứng minh những ràng buộc hiện có, không khẳng định hệ thống
-- đã chặn mọi thao tác lịch sử/đổi điểm đồng thời trong môi trường production.
DROP PROCEDURE IF EXISTS RunPhase3NegativeTests;
DELIMITER //
CREATE PROCEDURE RunPhase3NegativeTests()
SQL SECURITY INVOKER
BEGIN
    DECLARE v_errno INT DEFAULT 0;
    DECLARE v_sqlstate CHAR(5) DEFAULT '00000';
    DECLARE v_message VARCHAR(512) DEFAULT '';
    DECLARE v_conditions INT DEFAULT 0;
    DECLARE v_failed INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
    END;

    DROP TEMPORARY TABLE IF EXISTS phase3_negative_results;
    CREATE TEMPORARY TABLE phase3_negative_results (
        test_id VARCHAR(10) PRIMARY KEY,
        test_name VARCHAR(160),
        expected_errno INT,
        actual_errno INT,
        actual_sqlstate CHAR(5),
        result VARCHAR(4),
        error_message VARCHAR(512)
    ) ENGINE=MEMORY;

    START TRANSACTION;
        subtotal, delivery_fee, tax, total_amount, delivery_address) VALUES
    (-900001, 1, 1, '2026-10-01 10:00:00', 62000, 10000, 4960, 76960, 'NEGATIVE TEST ONLY'),
    (-900003, 1, 1, '2026-10-01 10:00:00', 62000, 10000, 4960, 76960, 'NEGATIVE TEST ONLY'),
    (-900004, 1, 1, '2026-10-01 10:00:00', 62000, 10000, 4960, 76960, 'NEGATIVE TEST ONLY'),
    (-900005, 1, 1, '2026-10-01 10:00:00', 62000, 10000, 4960, 76960, 'NEGATIVE TEST ONLY');


        assigned_at, accepted_at, completed_at) VALUES
    (-900001, -900001, 1, 'Assigned', '2026-10-01 10:05:00', NULL, NULL),
    (-900002, -900001, 2, 'Completed', '2026-10-01 10:01:00', '2026-10-01 10:02:00', '2026-10-01 10:04:00');

    -- Positive controls: dữ liệu hợp lệ phải INSERT được trước khi thử dữ liệu sai.
    VALUES (-900001, -900001, 1, 1, 62000, 1);
    VALUES (-900005, -900005, 1, 1, 5, '2026-10-01 10:50:00');

    -- NT01: Giá biến thể âm; mong đợi 3819 / chk_variant_price.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_variant_price', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT02: Số lượng món bằng 0; mong đợi 3819 / chk_order_item_quantity.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_order_item_quantity', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT03: Tổng tiền sai công thức; mong đợi 3819 / chk_orders_total.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_orders_total', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT04: Vĩ độ ngoài [-90,90]; mong đợi 3819 / chk_location_lat.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_location_lat', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT05: Loại xe không hợp lệ; mong đợi 3819 / chk_driver_vehicle.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_driver_vehicle', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT06: EARN có điểm âm; mong đợi 3819 / chk_loyalty_points.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_loyalty_points', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT07: Email khách hàng bị trùng; mong đợi 1062 / uq_customer_email.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1062 AND LOCATE('uq_customer_email', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT08: Món thuộc nhà hàng khác đơn; mong đợi 1452 / fk_order_item_variant_restaurant.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1452 AND LOCATE('fk_order_item_variant_restaurant', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT09: INSERT hai tài xế active cho một đơn; mong đợi 1644 / Order already has an active delivery assignment.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Order already has an active delivery assignment', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT10: UPDATE tạo hai lượt giao active; mong đợi 1644 / Order already has an active delivery assignment.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
        UPDATE DELIVERY_ASSIGNMENT SET status='Accepted' WHERE assignment_id=-900002;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Order already has an active delivery assignment', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT11: Đánh giá đơn đang Pending; mong đợi 1644 / Only currently delivered orders can be reviewed.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Only currently delivered orders can be reviewed', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT12: Điểm đánh giá lớn hơn 5; mong đợi 3819 / chk_review_rating.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_review_rating', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT13: Người đánh giá không phải chủ đơn; mong đợi 1452 / fk_review_order_identity.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1452 AND LOCATE('fk_review_order_identity', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT14: Có Delivered cũ nhưng trạng thái mới là Failed; mong đợi 1644 / Only currently delivered orders can be reviewed.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Only currently delivered orders can be reviewed', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT15: UPDATE đánh giá sang đơn Failed; mong đợi 1644 / Only currently delivered orders can be reviewed.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
        UPDATE REVIEW SET order_id=-900004 WHERE review_id=-900005;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Only currently delivered orders can be reviewed', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT16: Giao thất bại nhưng thiếu lý do; mong đợi 3819 / chk_assignment_failure.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 3819 AND LOCATE('chk_assignment_failure', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT17: Chuyển trạng thái Delivered về Preparing; mong đợi 1644 / Invalid order status transition.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
        CALL UpdateOrderStatus(-900003, 'Preparing', 'Invalid transition test');
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Invalid order status transition', v_message) > 0, 'PASS', 'FAIL'), v_message);

    -- NT18: Đánh giá trước thời điểm giao; mong đợi 1644 / Review cannot precede delivery.
    SET v_errno = 0, v_sqlstate = '00000', v_message = '';
    SAVEPOINT negative_case;
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        BEGIN
            GET STACKED DIAGNOSTICS v_conditions = NUMBER;
            GET STACKED DIAGNOSTICS CONDITION v_conditions
                v_errno = MYSQL_ERRNO, v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        END;
    END;
    ROLLBACK TO SAVEPOINT negative_case;
     IF(v_errno = 1644 AND LOCATE('Review cannot precede delivery', v_message) > 0, 'PASS', 'FAIL'), v_message);

    ROLLBACK;
    -- MEMORY chỉ giữ kết quả; mọi fixture trong các bảng InnoDB đã được hoàn tác.
    SELECT * FROM phase3_negative_results ORDER BY test_id;
    SELECT COUNT(*) AS total_tests,
           SUM(result = 'PASS') AS passed, SUM(result = 'FAIL') AS failed
    FROM phase3_negative_results;
    SELECT COUNT(*) INTO v_failed FROM phase3_negative_results WHERE result = 'FAIL';
    IF v_failed > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Negative tests failed; inspect result sets';
    END IF;
END //
DELIMITER ;
CALL RunPhase3NegativeTests();
DROP PROCEDURE RunPhase3NegativeTests;
DROP TEMPORARY TABLE phase3_negative_results;

-- ===================================================================
-- 5.2. RBAC - ROLE, GRANT, REVOKE, gán role cho tài khoản demo
-- ===================================================================
-- Thực thi mục này bằng DBA có CREATE ROLE/CREATE USER và quyền cấp tương ứng.
-- Đây là role cho nhân viên nội bộ, KHÔNG phải cơ chế lọc dữ liệu từng khách/tài xế.
-- Quyền cấp theo bảng/cột; quyền theo từng dòng cần lớp ứng dụng hoặc API riêng.
-- Các tên md_* dành cho bài thực hành này; không gán vào tài khoản đang sử dụng thật.
CREATE ROLE IF NOT EXISTS 'md_admin'@'localhost', 'md_order_staff'@'localhost',
                          'md_dispatcher'@'localhost', 'md_analyst'@'localhost';

-- Quản trị schema của dự án, không cấp quyền toàn máy chủ hay GRANT OPTION.
GRANT ALL PRIVILEGES ON food_delivery_phase3_workbench.* TO 'md_admin'@'localhost';

-- Nhân viên xử lý đơn: đọc thông tin cần thiết, không đọc password_hash.
GRANT SELECT (customer_id, first_name, last_name, email, phone_number)
    ON food_delivery_phase3_workbench.CUSTOMER TO 'md_order_staff'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.RESTAURANT TO 'md_order_staff'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.MENU_ITEM TO 'md_order_staff'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.MENU_ITEM_VARIANT TO 'md_order_staff'@'localhost';
GRANT SELECT, INSERT ON food_delivery_phase3_workbench.ORDERS TO 'md_order_staff'@'localhost';
GRANT SELECT, INSERT ON food_delivery_phase3_workbench.ORDER_ITEM TO 'md_order_staff'@'localhost';
GRANT SELECT, INSERT ON food_delivery_phase3_workbench.ORDER_NOTE TO 'md_order_staff'@'localhost';
GRANT SELECT, INSERT ON food_delivery_phase3_workbench.ORDER_ITEM_CUSTOMIZATION TO 'md_order_staff'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.ORDER_CURRENT_STATUS TO 'md_order_staff'@'localhost';
GRANT EXECUTE ON PROCEDURE food_delivery_phase3_workbench.FinalizeOrder TO 'md_order_staff'@'localhost';
GRANT EXECUTE ON PROCEDURE food_delivery_phase3_workbench.UpdateOrderStatus TO 'md_order_staff'@'localhost';
-- Không cấp INSERT/UPDATE trực tiếp ORDER_STATUS_HISTORY để tránh bỏ qua procedure.

-- Điều phối: phân công và cập nhật hành trình, không sửa giá trị hóa đơn.
GRANT SELECT ON food_delivery_phase3_workbench.DRIVER TO 'md_dispatcher'@'localhost';
GRANT SELECT (order_id, restaurant_id, delivery_address, special_instructions)
    ON food_delivery_phase3_workbench.ORDERS TO 'md_dispatcher'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.RESTAURANT TO 'md_dispatcher'@'localhost';
GRANT SELECT, INSERT ON food_delivery_phase3_workbench.DELIVERY_ASSIGNMENT TO 'md_dispatcher'@'localhost';
GRANT UPDATE (status, accepted_at, completed_at, failure_reason)
    ON food_delivery_phase3_workbench.DELIVERY_ASSIGNMENT TO 'md_dispatcher'@'localhost';
GRANT SELECT, INSERT ON food_delivery_phase3_workbench.LOCATION TO 'md_dispatcher'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.ORDER_CURRENT_STATUS TO 'md_dispatcher'@'localhost';
GRANT EXECUTE ON PROCEDURE food_delivery_phase3_workbench.UpdateOrderStatus TO 'md_dispatcher'@'localhost';

-- Phân tích: chỉ đọc báo cáo tổng hợp và thực đơn; không đọc PII/mật khẩu khách.
GRANT SELECT ON food_delivery_phase3_workbench.RESTAURANT_PERFORMANCE_SUMMARY TO 'md_analyst'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.RESTAURANT TO 'md_analyst'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.MENU_ITEM TO 'md_analyst'@'localhost';
GRANT SELECT ON food_delivery_phase3_workbench.MENU_ITEM_VARIANT TO 'md_analyst'@'localhost';
GRANT EXECUTE ON FUNCTION food_delivery_phase3_workbench.GetAvgRating TO 'md_analyst'@'localhost';

-- Minh họa thu hồi quyền: cấp UPDATE tạm thời cho role chưa gắn tài khoản demo,
-- xem quyền trước/sau rồi REVOKE. Kết quả cuối cùng analyst không còn UPDATE.
GRANT UPDATE ON food_delivery_phase3_workbench.MENU_ITEM TO 'md_analyst'@'localhost';
SHOW GRANTS FOR 'md_analyst'@'localhost';
REVOKE UPDATE ON food_delivery_phase3_workbench.MENU_ITEM FROM 'md_analyst'@'localhost';
SHOW GRANTS FOR 'md_analyst'@'localhost';

-- Tài khoản demo tạo ở trạng thái LOCK: không dùng mật khẩu cứng trong bài nộp.
CREATE USER IF NOT EXISTS 'md_demo_admin'@'localhost' ACCOUNT LOCK;
CREATE USER IF NOT EXISTS 'md_demo_orders'@'localhost' ACCOUNT LOCK;
CREATE USER IF NOT EXISTS 'md_demo_dispatch'@'localhost' ACCOUNT LOCK;
CREATE USER IF NOT EXISTS 'md_demo_analyst'@'localhost' ACCOUNT LOCK;
GRANT 'md_admin'@'localhost' TO 'md_demo_admin'@'localhost';
GRANT 'md_order_staff'@'localhost' TO 'md_demo_orders'@'localhost';
GRANT 'md_dispatcher'@'localhost' TO 'md_demo_dispatch'@'localhost';
GRANT 'md_analyst'@'localhost' TO 'md_demo_analyst'@'localhost';
SET DEFAULT ROLE 'md_admin'@'localhost' TO 'md_demo_admin'@'localhost';
SET DEFAULT ROLE 'md_order_staff'@'localhost' TO 'md_demo_orders'@'localhost';
SET DEFAULT ROLE 'md_dispatcher'@'localhost' TO 'md_demo_dispatch'@'localhost';
SET DEFAULT ROLE 'md_analyst'@'localhost' TO 'md_demo_analyst'@'localhost';

SHOW GRANTS FOR 'md_demo_orders'@'localhost' USING 'md_order_staff'@'localhost';
SHOW GRANTS FOR 'md_demo_dispatch'@'localhost' USING 'md_dispatcher'@'localhost';
SHOW GRANTS FOR 'md_demo_analyst'@'localhost' USING 'md_analyst'@'localhost';

